<?php require_once __DIR__.'/includes/bootstrap.php';require_role(['self']);$u=current_user();$iid=(int)($u['instructor_id']??0);if(!$iid){$s=$pdo->prepare('SELECT instructor_id FROM users WHERE id=?');$s->execute([$u['id']]);$iid=(int)($s->fetchColumn()?:0);}if(!$iid){page_header('My result');?><section class="panel"><h1>Instructor profile not linked</h1><p>Your account must be linked to the instructor name registered by the administrator. Open My profile, choose the instructor name registered by the administrator, and save. If your name is missing, ask the administrator to add it to the instructor directory.</p><a class="btn primary" href="<?=BASE_URL?>/profile.php">Link my profile</a></section><?php page_footer();exit;}
$s=$pdo->prepare('SELECT id,full_name,department,college FROM instructors WHERE id=? AND is_active=1');$s->execute([$iid]);$instructor=$s->fetch();if(!$instructor){page_header('My result');echo '<section class="panel"><h1>Instructor profile unavailable</h1><p>Ask the administrator to activate and link your instructor profile.</p></section>';page_footer();exit;}
$sql="SELECT e.evaluator_type,AVG(CASE WHEN r.is_na=0 THEN r.rating ELSE NULL END) avg_rating,COUNT(DISTINCT e.id) response_count FROM evaluations e LEFT JOIN evaluation_responses r ON r.evaluation_id=e.id WHERE e.instructor_id=? AND e.status IN ('submitted','committee_review','college_review','academic_affairs','archived') GROUP BY e.evaluator_type";$s=$pdo->prepare($sql);$s->execute([$iid]);$parts=[];foreach($s->fetchAll() as $r){if($r['avg_rating']!==null)$parts[$r['evaluator_type']]=['avg'=>(float)$r['avg_rating'],'count'=>(int)$r['response_count']];}$wm=weights();$labels=['student'=>'Student Evaluation','department_head'=>'Department Head','peer'=>'Peer Instructor','self'=>'Self-Evaluation'];$total=0;$available=0;page_header('My consolidated result');?><div class="page-intro"><div><div class="eyebrow">CONFIDENTIAL · AGGREGATED ONLY</div><h1>My evaluation result</h1><p><?=e($instructor['full_name'])?> · <?=e($instructor['department'])?></p></div></div><div class="notice">Only combined scores are displayed here. Individual submissions, comments, and evaluator identities are not available in this view.</div><section class="panel table-wrap"><table><thead><tr><th>Evaluation perspective</th><th>Average rating / 5</th><th>Weight</th><th>Weighted contribution</th><th>Responses</th></tr></thead><tbody><?php foreach($labels as $k=>$label):$part=$parts[$k]??null;$contrib=$part?($part['avg']/5*$wm[$k]):null;if($contrib!==null){$total+=$contrib;$available+=$wm[$k];}?><tr><td><?=e($label)?></td><td><?=$part?number_format($part['avg'],2):'Not available'?></td><td><?=$wm[$k]?>%</td><td><?=$contrib!==null?number_format($contrib,2).'%':'—'?></td><td><?=$part?$part['count']:'—'?></td></tr><?php endforeach;?><tr><td colspan="3"><b>Available weighted total</b></td><td colspan="2"><b><?=number_format($total,2)?>% of <?=$available?>% available weight</b></td></tr></tbody></table></section><?php page_footer();?>